import{_ as o,l as i,o as e,c as l,v as r,p as s,x as n,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"索引组织表","description":"","frontmatter":{"title":"索引组织表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/index-organized-table.md","filePath":"cs/index-organized-table.md","lastUpdated":1789023840000}'),h={name:"cs/index-organized-table.md"};function E(B,a,_,u,T,m){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="索引组织表" tabindex="-1">索引组织表 <a class="header-anchor" href="#索引组织表" aria-label="Permalink to &quot;索引组织表&quot;">​</a></h1><div class="epigraph"><p>没有独立堆：主键 B+ 的叶就是行。二级索引必须带回主键，范围主键是第一公民，随机主键是页分裂税。</p><footer>—— 据 Ramakrishnan and Gehrke index-organized；Oracle IOT；InnoDB 聚簇抽象</footer></div><p><a href="/cs/clustered-secondary-lookup">上一课</a>把回表说清。本课把聚簇一侧说绝：索引组织表（IOT）= 主键索引即表。引擎对照序列封口；事务进阶从时间戳排序再开。缺口是抽象合同，不只 InnoDB 商标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>堆表：插入有堆页选择（追加、FSM）。IOT：插入位置由主键唯一决定，叶满则分裂，与 B+ 分裂课同一算法，只是载荷是整行。溢出：行太大则叶存关键列+溢出指针，上一课变长仍适用。缺口是<strong>何时选 IOT</strong>：主键范围、点查 pk 为主、表不太宽；否则叶扇出差、二级回表键很长。</p><p>无主键：InnoDB 仍隐式聚簇行号；那是实现补丁，设计上应显式主键。Postgres 无 IOT 作为默认，堆是第一公民。</p><p><span class="marginnote">Oracle Index-Organized Tables 是教科书名字。二级索引存主键值，主键长则二级肥——复合主键要短。本课不推销某厂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计：短、稳定、与范围查询对齐的主键。二级：覆盖常用投影，减少回主键。分区可叠在 IOT 上（按主键前缀）。迁移堆→IOT 是整表重写。</p><p>并发：叶热点（单调主键插入）把 latch crabbing 打在同一右热叶上——可改哈希主键或打散，与 UUID 课的缓冲污染同一权衡。</p>',10)),(e(),s(c,null,{default:n(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PK%5B%22%E4%B8%BB%E9%94%AE%E9%94%AE%22%5D%20--%3E%20LEAF%5B%22%E5%8F%B6%E4%B8%8A%E6%95%B4%E8%A1%8C%22%5D%0A%20%20SEC%5B%22%E4%BA%8C%E7%BA%A7%22%5D%20--%3E%20PKV%5B%22%E5%AD%98%E4%B8%BB%E9%94%AE%E5%80%BC%22%5D%0A%20%20PKV%20--%3E%20LEAF%0A%20%20WIDE%5B%22%E8%BF%87%E5%AE%BD%E8%A1%8C%22%5D%20--%3E%20OV%5B%22%E6%BA%A2%E5%87%BA%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>扫描：主键序扫描即表扫描，zone map/BRIN 类结构在 IOT 上变成沿叶的区统计。vacuum：InnoDB purge undo；不是堆 vacuum，但叶页仍要合并。TDE 盖叶页与溢出页。</p><p>优化器：表扫描代价按叶链页数，不是堆占用（含空洞）的同一公式——膨胀定义不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲时间戳排序并发。也不把 IOT 当列存。存储进阶结束：从缓冲策略、索引族、列格式到两家行引擎。</p><p>后课默认：IOT 让 pk 范围顺序化，二级回主键。时间戳排序：不用 2PL，按时间戳接受或拒绝读写。</p><p>主键即布局。选错主键就是选错物理序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IOT 叶内存行；二级回主键；主键应短而稳定。</li><li>单调插入热叶是并发与缓冲问题。</li><li>下一单元时间戳排序：并发控制续的第一课。</li><li>出处：Ramakrishnan and Gehrke；Oracle IOT；InnoDB 聚簇。</li></ul>',9))])}const b=o(h,[["render",E]]);export{I as __pageData,b as default};
